query:
ALTER TABLE public.edutech_coefficients ADD COLUMN IF NOT EXISTS school_year text;
ALTER TABLE public.edutech_coefficients DROP CONSTRAINT IF EXISTS edutech_coefficients_school_year_check;
ALTER TABLE public.edutech_coefficients ADD CONSTRAINT edutech_coefficients_school_year_check CHECK (school_year IS NULL OR school_year ~ '^[0-9]{4}-[0-9]{4}$');
DROP INDEX IF EXISTS public.edutech_coefficients_offering_unique_idx;
DROP INDEX IF EXISTS public.edutech_coefficients_verified_offering_idx;
CREATE UNIQUE INDEX IF NOT EXISTS edutech_coefficients_offering_school_year_unique_idx ON public.edutech_coefficients(subject_offering_id, school_year) WHERE subject_offering_id IS NOT NULL AND school_year IS NOT NULL;
CREATE UNIQUE INDEX IF NOT EXISTS edutech_coefficients_offering_legacy_unique_idx ON public.edutech_coefficients(subject_offering_id) WHERE subject_offering_id IS NOT NULL AND school_year IS NULL;
CREATE INDEX IF NOT EXISTS edutech_coefficients_lookup_by_year_idx ON public.edutech_coefficients(level_id, series_id, subject_id, school_year) WHERE is_verified;
